00069 static Void scalePlane(Pel* img, const UInt stride, const UInt width, const UInt height, Int shiftbits, Pel minval, Pel maxval)
00070 {
00071   if (shiftbits > 0)
00072   {
00073     for (UInt y = 0; y < height; y++, img+=stride)
00074     {
00075       for (UInt x = 0; x < width; x++)
00076       {
00077         img[x] <<= shiftbits;
00078       }
00079     }
00080   }
00081   else if (shiftbits < 0)
00082   {
00083     shiftbits=-shiftbits;
00084 
00085     Pel rounding = 1 << (shiftbits-1);
00086     for (UInt y = 0; y < height; y++, img+=stride)
00087     {
00088       for (UInt x = 0; x < width; x++)
00089       {
00090         img[x] = Clip3(minval, maxval, Pel((img[x] + rounding) >> shiftbits));
00091       }
00092     }
00093   }
00094 }
