00119 Void TVideoIOYuvMem::open(Writer *writer, const Int fileBitDepth[MAX_NUM_CHANNEL_TYPE], const Int MSBExtendedBitDepth[MAX_NUM_CHANNEL_TYPE], const Int internalBitDepth[MAX_NUM_CHANNEL_TYPE] )
00120 {
00121   //NOTE: files cannot have bit depth greater than 16
00122   for(UInt ch=0; ch<MAX_NUM_CHANNEL_TYPE; ch++)
00123   {
00124     m_fileBitdepth       [ch] = std::min<UInt>(fileBitDepth[ch], 16);
00125     m_MSBExtendedBitDepth[ch] = MSBExtendedBitDepth[ch];
00126     m_bitdepthShift      [ch] = internalBitDepth[ch] - m_MSBExtendedBitDepth[ch];
00127 
00128     if (m_fileBitdepth[ch] > 16)
00129     {
00130         std::cerr << "\nWARNING: Cannot write a yuv file of bit depth greater than 16 - output will be right-shifted down to 16-bit precision\n" << std::endl;
00131     }
00132   }
00133 
00134   m_writer = writer;
00135 
00136   return;
00137 }
