00160 Void TVideoIOYuvMem::skipFrames(Int numFrames, UInt width, UInt height, ChromaFormat format)
00161 {
00162   if (numFrames==0)
00163   {
00164     return;
00165   }
00166 
00167   //------------------
00168   //set the frame size according to the chroma format
00169   streamoff frameSize = 0;
00170   UInt wordsize=1; // default to 8-bit, unless a channel with more than 8-bits is detected.
00171   for (UInt component = 0; component < getNumberValidComponents(format); component++)
00172   {
00173     ComponentID compID=ComponentID(component);
00174     frameSize += (width >> getComponentScaleX(compID, format)) * (height >> getComponentScaleY(compID, format));
00175     if (m_fileBitdepth[toChannelType(compID)] > 8)
00176     {
00177       wordsize=2;
00178     }
00179   }
00180   frameSize *= wordsize;
00181   //------------------
00182 
00183   const streamoff offset = frameSize * numFrames;
00184 
00185 #if 0
00186   /* attempt to seek */
00187   if (!!m_cHandle.seekg(offset, ios::cur))
00188   {
00189     return; /* success */
00190   }
00191   m_cHandle.clear();
00192 
00193   /* fall back to consuming the input */
00194   TChar buf[512];
00195   const streamoff offset_mod_bufsize = offset % sizeof(buf);
00196   for (streamoff i = 0; i < offset - offset_mod_bufsize; i += sizeof(buf))
00197   {
00198     m_cHandle.read(buf, sizeof(buf));
00199   }
00200   m_cHandle.read(buf, offset_mod_bufsize);
00201 #endif
00202 }
