00223 static Bool readPlane(Pel* dst,
00224                       istream& fd,
00225                       Bool is16bit,
00226                       UInt stride444,
00227                       UInt width444,
00228                       UInt height444,
00229                       UInt pad_x444,
00230                       UInt pad_y444,
00231                       const ComponentID compID,
00232                       const ChromaFormat destFormat,
00233                       const ChromaFormat fileFormat,
00234                       const UInt fileBitDepth)
00235 {
00236   const UInt csx_file =getComponentScaleX(compID, fileFormat);
00237   const UInt csy_file =getComponentScaleY(compID, fileFormat);
00238   const UInt csx_dest =getComponentScaleX(compID, destFormat);
00239   const UInt csy_dest =getComponentScaleY(compID, destFormat);
00240 
00241   const UInt width_dest       = width444 >>csx_dest;
00242   const UInt height_dest      = height444>>csy_dest;
00243   const UInt pad_x_dest       = pad_x444>>csx_dest;
00244   const UInt pad_y_dest       = pad_y444>>csy_dest;
00245   const UInt stride_dest      = stride444>>csx_dest;
00246 
00247   const UInt full_width_dest  = width_dest+pad_x_dest;
00248   const UInt full_height_dest = height_dest+pad_y_dest;
00249 
00250   const UInt stride_file      = (width444 * (is16bit ? 2 : 1)) >> csx_file;
00251   std::vector<UChar> bufVec(stride_file);
00252   UChar *buf=&(bufVec[0]);
00253 
00254   if (compID!=COMPONENT_Y && (fileFormat==CHROMA_400 || destFormat==CHROMA_400))
00255   {
00256     if (destFormat!=CHROMA_400)
00257     {
00258       // set chrominance data to mid-range: (1<<(fileBitDepth-1))
00259       const Pel value=Pel(1<<(fileBitDepth-1));
00260       for (UInt y = 0; y < full_height_dest; y++, dst+=stride_dest)
00261       {
00262         for (UInt x = 0; x < full_width_dest; x++)
00263         {
00264           dst[x] = value;
00265         }
00266       }
00267     }
00268 
00269     if (fileFormat!=CHROMA_400)
00270     {
00271       const UInt height_file      = height444>>csy_file;
00272       fd.seekg(height_file*stride_file, ios::cur);
00273       if (fd.eof() || fd.fail() )
00274       {
00275         return false;
00276       }
00277     }
00278   }
00279   else
00280   {
00281     const UInt mask_y_file=(1<<csy_file)-1;
00282     const UInt mask_y_dest=(1<<csy_dest)-1;
00283     for(UInt y444=0; y444<height444; y444++)
00284     {
00285       if ((y444&mask_y_file)==0)
00286       {
00287         // read a new line
00288         fd.read(reinterpret_cast<TChar*>(buf), stride_file);
00289         if (fd.eof() || fd.fail() )
00290         {
00291           return false;
00292         }
00293       }
00294 
00295       if ((y444&mask_y_dest)==0)
00296       {
00297         // process current destination line
00298         if (csx_file < csx_dest)
00299         {
00300           // eg file is 444, dest is 422.
00301           const UInt sx=csx_dest-csx_file;
00302           if (!is16bit)
00303           {
00304             for (UInt x = 0; x < width_dest; x++)
00305             {
00306               dst[x] = buf[x<<sx];
00307             }
00308           }
00309           else
00310           {
00311             for (UInt x = 0; x < width_dest; x++)
00312             {
00313               dst[x] = Pel(buf[(x<<sx)*2+0]) | (Pel(buf[(x<<sx)*2+1])<<8);
00314             }
00315           }
00316         }
00317         else
00318         {
00319           // eg file is 422, dest is 444.
00320           const UInt sx=csx_file-csx_dest;
00321           if (!is16bit)
00322           {
00323             for (UInt x = 0; x < width_dest; x++)
00324             {
00325               dst[x] = buf[x>>sx];
00326             }
00327           }
00328           else
00329           {
00330             for (UInt x = 0; x < width_dest; x++)
00331             {
00332               dst[x] = Pel(buf[(x>>sx)*2+0]) | (Pel(buf[(x>>sx)*2+1])<<8);
00333             }
00334           }
00335         }
00336 
00337         // process right hand side padding
00338         const Pel val=dst[width_dest-1];
00339         for (UInt x = width_dest; x < full_width_dest; x++)
00340         {
00341           dst[x] = val;
00342         }
00343 
00344         dst += stride_dest;
00345       }
00346     }
00347 
00348     // process lower padding
00349     for (UInt y = height_dest; y < full_height_dest; y++, dst+=stride_dest)
00350     {
00351       for (UInt x = 0; x < full_width_dest; x++)
00352       {
00353         dst[x] = (dst - stride_dest)[x];
00354       }
00355     }
00356   }
00357   return true;
00358 }
