00375 static Bool writePlane(TVideoIOYuvMem::Writer *writer, Pel* src, Bool is16bit,
00376                        UInt stride444,
00377                        UInt width444, UInt height444,
00378                        const ComponentID compID,
00379                        const ChromaFormat srcFormat,
00380                        const ChromaFormat fileFormat,
00381                        const UInt fileBitDepth)
00382 {
00383   const UInt csx_file =getComponentScaleX(compID, fileFormat);
00384   const UInt csy_file =getComponentScaleY(compID, fileFormat);
00385   const UInt csx_src  =getComponentScaleX(compID, srcFormat);
00386   const UInt csy_src  =getComponentScaleY(compID, srcFormat);
00387 
00388   const UInt stride_src      = stride444>>csx_src;
00389 
00390   const UInt stride_file      = (width444 * (is16bit ? 2 : 1)) >> csx_file;
00391   const UInt width_file       = width444 >>csx_file;
00392   const UInt height_file      = height444>>csy_file;
00393 
00394   std::vector<UChar> bufVec(stride_file);
00395   UChar *buf=&(bufVec[0]);
00396 
00397   if (compID!=COMPONENT_Y && (fileFormat==CHROMA_400 || srcFormat==CHROMA_400))
00398   {
00399     if (fileFormat!=CHROMA_400)
00400     {
00401       const UInt value=1<<(fileBitDepth-1);
00402 
00403       for(UInt y=0; y< height_file; y++)
00404       {
00405         if (!is16bit)
00406         {
00407           UChar val(value);
00408           for (UInt x = 0; x < width_file; x++)
00409           {
00410             buf[x]=val;
00411           }
00412         }
00413         else
00414         {
00415           UShort val(value);
00416           for (UInt x = 0; x < width_file; x++)
00417           {
00418             buf[2*x+0]= (val>>0) & 0xff;
00419             buf[2*x+1]= (val>>8) & 0xff;
00420           }
00421         }
00422 
00423         writer->write(reinterpret_cast<const uint8_t*>(buf), stride_file);
00424 //        if (fd.eof() || fd.fail() )
00425 //        {
00426 //          return false;
00427 //        }
00428       }
00429     }
00430   }
00431   else
00432   {
00433     const UInt mask_y_file=(1<<csy_file)-1;
00434     const UInt mask_y_src =(1<<csy_src )-1;
00435     for(UInt y444=0; y444<height444; y444++)
00436     {
00437       if ((y444&mask_y_file)==0)
00438       {
00439         // write a new line
00440         if (csx_file < csx_src)
00441         {
00442           // eg file is 444, source is 422.
00443           const UInt sx=csx_src-csx_file;
00444           if (!is16bit)
00445           {
00446             for (UInt x = 0; x < width_file; x++)
00447             {
00448               buf[x] = (UChar)(src[x>>sx]);
00449             }
00450           }
00451           else
00452           {
00453             for (UInt x = 0; x < width_file; x++)
00454             {
00455               buf[2*x  ] = (src[x>>sx]>>0) & 0xff;
00456               buf[2*x+1] = (src[x>>sx]>>8) & 0xff;
00457             }
00458           }
00459         }
00460         else
00461         {
00462           // eg file is 422, src is 444.
00463           const UInt sx=csx_file-csx_src;
00464           if (!is16bit)
00465           {
00466             for (UInt x = 0; x < width_file; x++)
00467             {
00468               buf[x] = (UChar)(src[x<<sx]);
00469             }
00470           }
00471           else
00472           {
00473             for (UInt x = 0; x < width_file; x++)
00474             {
00475               buf[2*x  ] = (src[x<<sx]>>0) & 0xff;
00476               buf[2*x+1] = (src[x<<sx]>>8) & 0xff;
00477             }
00478           }
00479         }
00480 
00481         writer->write(reinterpret_cast<const uint8_t*>(buf), stride_file);
00482 //        if (fd.eof() || fd.fail() )
00483 //        {
00484 //          return false;
00485 //        }
00486       }
00487 
00488       if ((y444&mask_y_src)==0)
00489       {
00490         src += stride_src;
00491       }
00492 
00493     }
00494   }
00495   return true;
00496 }
