00498 static Bool writeField(TVideoIOYuvMem::Writer *writer, Pel* top, Pel* bottom, Bool is16bit,
00499                        UInt stride444,
00500                        UInt width444, UInt height444,
00501                        const ComponentID compID,
00502                        const ChromaFormat srcFormat,
00503                        const ChromaFormat fileFormat,
00504                        const UInt fileBitDepth, const Bool isTff)
00505 {
00506   const UInt csx_file =getComponentScaleX(compID, fileFormat);
00507   const UInt csy_file =getComponentScaleY(compID, fileFormat);
00508   const UInt csx_src  =getComponentScaleX(compID, srcFormat);
00509   const UInt csy_src  =getComponentScaleY(compID, srcFormat);
00510 
00511   const UInt stride_src      = stride444>>csx_src;
00512 
00513   const UInt stride_file      = (width444 * (is16bit ? 2 : 1)) >> csx_file;
00514   const UInt width_file       = width444 >>csx_file;
00515   const UInt height_file      = height444>>csy_file;
00516 
00517   std::vector<UChar> bufVec(stride_file * 2);
00518   UChar *buf=&(bufVec[0]);
00519 
00520   if (compID!=COMPONENT_Y && (fileFormat==CHROMA_400 || srcFormat==CHROMA_400))
00521   {
00522     if (fileFormat!=CHROMA_400)
00523     {
00524       const UInt value=1<<(fileBitDepth-1);
00525 
00526       for(UInt y=0; y< height_file; y++)
00527       {
00528         for (UInt field = 0; field < 2; field++)
00529         {
00530           UChar *fieldBuffer = buf + (field * stride_file);
00531 
00532           if (!is16bit)
00533           {
00534             UChar val(value);
00535             for (UInt x = 0; x < width_file; x++)
00536             {
00537               fieldBuffer[x]=val;
00538             }
00539           }
00540           else
00541           {
00542             UShort val(value);
00543             for (UInt x = 0; x < width_file; x++)
00544             {
00545               fieldBuffer[2*x+0]= (val>>0) & 0xff;
00546               fieldBuffer[2*x+1]= (val>>8) & 0xff;
00547             }
00548           }
00549         }
00550 
00551         writer->write(reinterpret_cast<const uint8_t*>(buf), (stride_file * 2));
00552 //        if (fd.eof() || fd.fail() )
00553 //        {
00554 //          return false;
00555 //        }
00556       }
00557     }
00558   }
00559   else
00560   {
00561     const UInt mask_y_file=(1<<csy_file)-1;
00562     const UInt mask_y_src =(1<<csy_src )-1;
00563     for(UInt y444=0; y444<height444; y444++)
00564     {
00565       if ((y444&mask_y_file)==0)
00566       {
00567         for (UInt field = 0; field < 2; field++)
00568         {
00569           UChar *fieldBuffer = buf + (field * stride_file);
00570           Pel   *src         = (((field == 0) && isTff) || ((field == 1) && (!isTff))) ? top : bottom;
00571 
00572           // write a new line
00573           if (csx_file < csx_src)
00574           {
00575             // eg file is 444, source is 422.
00576             const UInt sx=csx_src-csx_file;
00577             if (!is16bit)
00578             {
00579               for (UInt x = 0; x < width_file; x++)
00580               {
00581                 fieldBuffer[x] = (UChar)(src[x>>sx]);
00582               }
00583             }
00584             else
00585             {
00586               for (UInt x = 0; x < width_file; x++)
00587               {
00588                 fieldBuffer[2*x  ] = (src[x>>sx]>>0) & 0xff;
00589                 fieldBuffer[2*x+1] = (src[x>>sx]>>8) & 0xff;
00590               }
00591             }
00592           }
00593           else
00594           {
00595             // eg file is 422, src is 444.
00596             const UInt sx=csx_file-csx_src;
00597             if (!is16bit)
00598             {
00599               for (UInt x = 0; x < width_file; x++)
00600               {
00601                 fieldBuffer[x] = (UChar)(src[x<<sx]);
00602               }
00603             }
00604             else
00605             {
00606               for (UInt x = 0; x < width_file; x++)
00607               {
00608                 fieldBuffer[2*x  ] = (src[x<<sx]>>0) & 0xff;
00609                 fieldBuffer[2*x+1] = (src[x<<sx]>>8) & 0xff;
00610               }
00611             }
00612           }
00613         }
00614 
00615         writer->write(reinterpret_cast<const uint8_t*>(buf), (stride_file * 2));
00616 //        if (fd.eof() || fd.fail() )
00617 //        {
00618 //          return false;
00619 //        }
00620       }
00621 
00622       if ((y444&mask_y_src)==0)
00623       {
00624         top    += stride_src;
00625         bottom += stride_src;
00626       }
00627 
00628     }
00629   }
00630   return true;
00631 }
