00649 Bool TVideoIOYuvMem::read ( TComPicYuv*  pPicYuvUser, TComPicYuv* pPicYuvTrueOrg, const InputColourSpaceConversion ipcsc, Int aiPad[2], ChromaFormat format, const Bool bClipToRec709 )
00650 {
00651   // check end-of-file
00652   if ( isEof() )
00653   {
00654     return false;
00655   }
00656   TComPicYuv *pPicYuv=pPicYuvTrueOrg;
00657   if (format>=NUM_CHROMA_FORMAT)
00658   {
00659     format=pPicYuv->getChromaFormat();
00660   }
00661 
00662   Bool is16bit = false;
00663 
00664   for(UInt ch=0; ch<MAX_NUM_CHANNEL_TYPE; ch++)
00665   {
00666     if (m_fileBitdepth[ch] > 8)
00667     {
00668       is16bit=true;
00669     }
00670   }
00671 
00672   const UInt stride444      = pPicYuv->getStride(COMPONENT_Y);
00673 
00674   // compute actual YUV width & height excluding padding size
00675   const UInt pad_h444       = aiPad[0];
00676   const UInt pad_v444       = aiPad[1];
00677 
00678   const UInt width_full444  = pPicYuv->getWidth(COMPONENT_Y);
00679   const UInt height_full444 = pPicYuv->getHeight(COMPONENT_Y);
00680 
00681   const UInt width444       = width_full444 - pad_h444;
00682   const UInt height444      = height_full444 - pad_v444;
00683 
00684   for(UInt comp=0; comp<MAX_NUM_COMPONENT; comp++)
00685   {
00686     const ComponentID compID = ComponentID(comp);
00687     const ChannelType chType=toChannelType(compID);
00688 
00689     const Int desired_bitdepth = m_MSBExtendedBitDepth[chType] + m_bitdepthShift[chType];
00690 
00691     const Bool b709Compliance=(bClipToRec709) && (m_bitdepthShift[chType] < 0 && desired_bitdepth >= 8);     /* ITU-R BT.709 compliant clipping for converting say 10b to 8b */
00692     const Pel minval = b709Compliance? ((   1 << (desired_bitdepth - 8))   ) : 0;
00693     const Pel maxval = b709Compliance? ((0xff << (desired_bitdepth - 8)) -1) : (1 << desired_bitdepth) - 1;
00694 
00695 #if 0   
00696     if (! readPlane(pPicYuv->getAddr(compID), m_cHandle, is16bit, stride444, width444, height444, pad_h444, pad_v444, compID, pPicYuv->getChromaFormat(), format, m_fileBitdepth[chType]))
00697     {
00698       return false;
00699     }
00700 #endif
00701     if (compID < pPicYuv->getNumberValidComponents() )
00702     {
00703       const UInt csx=getComponentScaleX(compID, pPicYuv->getChromaFormat());
00704       const UInt csy=getComponentScaleY(compID, pPicYuv->getChromaFormat());
00705       scalePlane(pPicYuv->getAddr(compID), stride444>>csx, width_full444>>csx, height_full444>>csy, m_bitdepthShift[chType], minval, maxval);
00706     }
00707   }
00708 
00709   if(pPicYuvUser)
00710   {
00711     ColourSpaceConvert(*pPicYuvTrueOrg, *pPicYuvUser, ipcsc, true);
00712   }
00713 
00714   return true;
00715 }
