00730 Bool TVideoIOYuvMem::write( TComPicYuv* pPicYuvUser, const InputColourSpaceConversion ipCSC, Int confLeft, Int confRight, Int confTop, Int confBottom, ChromaFormat format, const Bool bClipToRec709 )
00731 {
00732   TComPicYuv cPicYuvCSCd;
00733   if (ipCSC!=IPCOLOURSPACE_UNCHANGED)
00734   {
00735     cPicYuvCSCd.createWithoutCUInfo(pPicYuvUser->getWidth(COMPONENT_Y), pPicYuvUser->getHeight(COMPONENT_Y), pPicYuvUser->getChromaFormat() );
00736     ColourSpaceConvert(*pPicYuvUser, cPicYuvCSCd, ipCSC, false);
00737   }
00738   TComPicYuv *pPicYuv=(ipCSC==IPCOLOURSPACE_UNCHANGED) ? pPicYuvUser : &cPicYuvCSCd;
00739 
00740   // compute actual YUV frame size excluding padding size
00741   Bool is16bit = false;
00742   Bool nonZeroBitDepthShift=false;
00743 
00744   for(UInt ch=0; ch<MAX_NUM_CHANNEL_TYPE; ch++)
00745   {
00746     if (m_fileBitdepth[ch] > 8)
00747     {
00748       is16bit=true;
00749     }
00750     if (m_bitdepthShift[ch] != 0)
00751     {
00752       nonZeroBitDepthShift=true;
00753     }
00754   }
00755 
00756   TComPicYuv *dstPicYuv = NULL;
00757   Bool retval = true;
00758   if (format>=NUM_CHROMA_FORMAT)
00759   {
00760     format=pPicYuv->getChromaFormat();
00761   }
00762 
00763   if (nonZeroBitDepthShift)
00764   {
00765     dstPicYuv = new TComPicYuv;
00766     dstPicYuv->createWithoutCUInfo( pPicYuv->getWidth(COMPONENT_Y), pPicYuv->getHeight(COMPONENT_Y), pPicYuv->getChromaFormat() );
00767 
00768     for(UInt comp=0; comp<dstPicYuv->getNumberValidComponents(); comp++)
00769     {
00770       const ComponentID compID=ComponentID(comp);
00771       const ChannelType ch=toChannelType(compID);
00772       const Bool b709Compliance = bClipToRec709 && (-m_bitdepthShift[ch] < 0 && m_MSBExtendedBitDepth[ch] >= 8);     /* ITU-R BT.709 compliant clipping for converting say 10b to 8b */
00773       const Pel minval = b709Compliance? ((   1 << (m_MSBExtendedBitDepth[ch] - 8))   ) : 0;
00774       const Pel maxval = b709Compliance? ((0xff << (m_MSBExtendedBitDepth[ch] - 8)) -1) : (1 << m_MSBExtendedBitDepth[ch]) - 1;
00775 
00776       copyPlane(*pPicYuv, compID, *dstPicYuv, compID);
00777       scalePlane(dstPicYuv->getAddr(compID), dstPicYuv->getStride(compID), dstPicYuv->getWidth(compID), dstPicYuv->getHeight(compID), -m_bitdepthShift[ch], minval, maxval);
00778     }
00779   }
00780   else
00781   {
00782     dstPicYuv = pPicYuv;
00783   }
00784 
00785   const Int  stride444 = dstPicYuv->getStride(COMPONENT_Y);
00786   const UInt width444  = dstPicYuv->getWidth(COMPONENT_Y) - confLeft - confRight;
00787   const UInt height444 = dstPicYuv->getHeight(COMPONENT_Y) -  confTop  - confBottom;
00788 
00789   if ((width444 == 0) || (height444 == 0))
00790   {
00791     printf ("\nWarning: writing %d x %d luma sample output picture!", width444, height444);
00792   }
00793 
00794   m_writer->picture_begin(is16bit, width444, height444, dstPicYuv->getChromaFormat());
00795   for(UInt comp=0; retval && comp<dstPicYuv->getNumberValidComponents(); comp++)
00796   {
00797     const ComponentID compID = ComponentID(comp);
00798     const ChannelType ch=toChannelType(compID);
00799     const UInt csx = dstPicYuv->getComponentScaleX(compID);
00800     const UInt csy = dstPicYuv->getComponentScaleY(compID);
00801     const Int planeOffset =  (confLeft>>csx) + (confTop>>csy) * dstPicYuv->getStride(compID);
00802     if (! writePlane(m_writer, dstPicYuv->getAddr(compID) + planeOffset, is16bit, stride444, width444, height444, compID, dstPicYuv->getChromaFormat(), format, m_fileBitdepth[ch]))
00803     {
00804       retval=false;
00805     }
00806   }
00807 
00808   m_writer->picture_end();
00809 
00810   if (nonZeroBitDepthShift)
00811   {
00812     dstPicYuv->destroy();
00813     delete dstPicYuv;
00814   }
00815 
00816   cPicYuvCSCd.destroy();
00817 
00818   return retval;
00819 }
00820 
00821 Bool TVideoIOYuvMem::write( TComPicYuv* pPicYuvUserTop, TComPicYuv* pPicYuvUserBottom, const InputColourSpaceConversion ipCSC, Int confLeft, Int confRight, Int confTop, Int confBottom, ChromaFormat format, const Bool isTff, const Bool bClipToRec709 )
00822 {
00823 
00824   TComPicYuv cPicYuvTopCSCd;
00825   TComPicYuv cPicYuvBottomCSCd;
00826   if (ipCSC!=IPCOLOURSPACE_UNCHANGED)
00827   {
00828     cPicYuvTopCSCd   .createWithoutCUInfo(pPicYuvUserTop   ->getWidth(COMPONENT_Y), pPicYuvUserTop   ->getHeight(COMPONENT_Y), pPicYuvUserTop   ->getChromaFormat() );
00829     cPicYuvBottomCSCd.createWithoutCUInfo(pPicYuvUserBottom->getWidth(COMPONENT_Y), pPicYuvUserBottom->getHeight(COMPONENT_Y), pPicYuvUserBottom->getChromaFormat() );
00830     ColourSpaceConvert(*pPicYuvUserTop,    cPicYuvTopCSCd,    ipCSC, false);
00831     ColourSpaceConvert(*pPicYuvUserBottom, cPicYuvBottomCSCd, ipCSC, false);
00832   }
00833   TComPicYuv *pPicYuvTop    = (ipCSC==IPCOLOURSPACE_UNCHANGED) ? pPicYuvUserTop    : &cPicYuvTopCSCd;
00834   TComPicYuv *pPicYuvBottom = (ipCSC==IPCOLOURSPACE_UNCHANGED) ? pPicYuvUserBottom : &cPicYuvBottomCSCd;
00835 
00836   Bool is16bit = false;
00837   Bool nonZeroBitDepthShift=false;
00838 
00839   for(UInt ch=0; ch<MAX_NUM_CHANNEL_TYPE; ch++)
00840   {
00841     if (m_fileBitdepth[ch] > 8)
00842     {
00843       is16bit=true;
00844     }
00845     if (m_bitdepthShift[ch] != 0)
00846     {
00847       nonZeroBitDepthShift=true;
00848     }
00849   }
00850 
00851   TComPicYuv *dstPicYuvTop    = NULL;
00852   TComPicYuv *dstPicYuvBottom = NULL;
00853 
00854   for (UInt field = 0; field < 2; field++)
00855   {
00856     TComPicYuv *pPicYuv = (field == 0) ? pPicYuvTop : pPicYuvBottom;
00857 
00858     if (format>=NUM_CHROMA_FORMAT)
00859     {
00860       format=pPicYuv->getChromaFormat();
00861     }
00862 
00863     TComPicYuv* &dstPicYuv = (field == 0) ? dstPicYuvTop : dstPicYuvBottom;
00864 
00865     if (nonZeroBitDepthShift)
00866     {
00867       dstPicYuv = new TComPicYuv;
00868       dstPicYuv->createWithoutCUInfo( pPicYuv->getWidth(COMPONENT_Y), pPicYuv->getHeight(COMPONENT_Y), pPicYuv->getChromaFormat() );
00869 
00870       for(UInt comp=0; comp<dstPicYuv->getNumberValidComponents(); comp++)
00871       {
00872         const ComponentID compID=ComponentID(comp);
00873         const ChannelType ch=toChannelType(compID);
00874         const Bool b709Compliance=bClipToRec709 && (-m_bitdepthShift[ch] < 0 && m_MSBExtendedBitDepth[ch] >= 8);     /* ITU-R BT.709 compliant clipping for converting say 10b to 8b */
00875         const Pel minval = b709Compliance? ((   1 << (m_MSBExtendedBitDepth[ch] - 8))   ) : 0;
00876         const Pel maxval = b709Compliance? ((0xff << (m_MSBExtendedBitDepth[ch] - 8)) -1) : (1 << m_MSBExtendedBitDepth[ch]) - 1;
00877 
00878         copyPlane(*pPicYuv, compID, *dstPicYuv, compID);
00879         scalePlane(dstPicYuv->getAddr(compID), dstPicYuv->getStride(compID), dstPicYuv->getWidth(compID), dstPicYuv->getHeight(compID), -m_bitdepthShift[ch], minval, maxval);
00880       }
00881     }
00882     else
00883     {
00884       dstPicYuv = pPicYuv;
00885     }
00886   }
00887 
00888   Bool retval = true;
00889 
00890   assert(dstPicYuvTop->getNumberValidComponents() == dstPicYuvBottom->getNumberValidComponents());
00891   assert(dstPicYuvTop->getChromaFormat()          == dstPicYuvBottom->getChromaFormat()         );
00892 
00893   {
00894     const UInt width444   = dstPicYuvTop->getWidth(COMPONENT_Y)  - (confLeft + confRight);
00895     const UInt height444  = dstPicYuvTop->getHeight(COMPONENT_Y) - (confTop + confBottom);
00896 
00897     m_writer->picture_begin(is16bit, width444, height444, dstPicYuvTop->getChromaFormat());
00898   }
00899 
00900   for(UInt comp=0; retval && comp<dstPicYuvTop->getNumberValidComponents(); comp++)
00901   {
00902     const ComponentID compID = ComponentID(comp);
00903     const ChannelType ch=toChannelType(compID);
00904 
00905     assert(dstPicYuvTop->getWidth          (compID) == dstPicYuvBottom->getWidth          (compID));
00906     assert(dstPicYuvTop->getHeight         (compID) == dstPicYuvBottom->getHeight         (compID));
00907     assert(dstPicYuvTop->getComponentScaleX(compID) == dstPicYuvBottom->getComponentScaleX(compID));
00908     assert(dstPicYuvTop->getComponentScaleY(compID) == dstPicYuvBottom->getComponentScaleY(compID));
00909     assert(dstPicYuvTop->getStride         (compID) == dstPicYuvBottom->getStride         (compID));
00910 
00911     const UInt width444   = dstPicYuvTop->getWidth(COMPONENT_Y)  - (confLeft + confRight);
00912     const UInt height444  = dstPicYuvTop->getHeight(COMPONENT_Y) - (confTop + confBottom);
00913 
00914     if ((width444 == 0) || (height444 == 0))
00915     {
00916       printf ("\nWarning: writing %d x %d luma sample output picture!", width444, height444);
00917     }
00918 
00919     const UInt csx = dstPicYuvTop->getComponentScaleX(compID);
00920     const UInt csy = dstPicYuvTop->getComponentScaleY(compID);
00921     const Int planeOffset  = (confLeft>>csx) + ( confTop>>csy) * dstPicYuvTop->getStride(compID); //offset is for entire frame - round up for top field and down for bottom field
00922 
00923     if (! writeField(m_writer,
00924                      (dstPicYuvTop   ->getAddr(compID) + planeOffset),
00925                      (dstPicYuvBottom->getAddr(compID) + planeOffset),
00926                      is16bit,
00927                      dstPicYuvTop->getStride(COMPONENT_Y),
00928                      width444, height444, compID, dstPicYuvTop->getChromaFormat(), format, m_fileBitdepth[ch], isTff))
00929     {
00930       retval=false;
00931     }
00932   }
00933 
00934   m_writer->picture_end();
00935  
00936   if (nonZeroBitDepthShift)
00937   {
00938     dstPicYuvTop->destroy();
00939     dstPicYuvBottom->destroy();
00940     delete dstPicYuvTop;
00941     delete dstPicYuvBottom;
00942   }
00943 
00944   cPicYuvTopCSCd.destroy();
00945   cPicYuvBottomCSCd.destroy();
00946 
00947   return retval;
00948 }
00949 
00950 static Void
00951 copyPlane(const TComPicYuv &src, const ComponentID srcPlane, TComPicYuv &dest, const ComponentID destPlane)
00952 {
00953   const UInt width=src.getWidth(srcPlane);
00954   const UInt height=src.getHeight(srcPlane);
00955   assert(dest.getWidth(destPlane) == width);
00956   assert(dest.getHeight(destPlane) == height);
00957   const Pel *pSrc=src.getAddr(srcPlane);
00958   Pel *pDest=dest.getAddr(destPlane);
00959   const UInt strideSrc=src.getStride(srcPlane);
00960   const UInt strideDest=dest.getStride(destPlane);
00961   for(UInt y=0; y<height; y++, pSrc+=strideSrc, pDest+=strideDest)
00962   {
00963     memcpy(pDest, pSrc, width*sizeof(Pel));
00964   }
00965 }
00966 
00967 // static member
00968 Void TVideoIOYuvMem::ColourSpaceConvert(const TComPicYuv &src, TComPicYuv &dest, const InputColourSpaceConversion conversion, Bool bIsForwards)
00969 {
00970   const ChromaFormat  format=src.getChromaFormat();
00971   const UInt          numValidComp=src.getNumberValidComponents();
00972 
00973   switch (conversion)
00974   {
00975     case IPCOLOURSPACE_YCbCrtoYYY:
00976       if (format!=CHROMA_444)
00977       {
00978         // only 444 is handled.
00979         assert(format==CHROMA_444);
00980         exit(1);
00981       }
00982 
00983       {
00984         for(UInt comp=0; comp<numValidComp; comp++)
00985         {
00986           copyPlane(src, ComponentID(bIsForwards?0:comp), dest, ComponentID(comp));
00987         }
00988       }
00989       break;
00990     case IPCOLOURSPACE_YCbCrtoYCrCb:
00991       {
00992         for(UInt comp=0; comp<numValidComp; comp++)
00993         {
00994           copyPlane(src, ComponentID(comp), dest, ComponentID((numValidComp-comp)%numValidComp));
00995         }
00996       }
00997       break;
00998 
00999     case IPCOLOURSPACE_RGBtoGBR:
01000       {
01001         if (format!=CHROMA_444)
01002         {
01003           // only 444 is handled.
01004           assert(format==CHROMA_444);
01005           exit(1);
01006         }
01007 
01008         // channel re-mapping
01009         for(UInt comp=0; comp<numValidComp; comp++)
01010         {
01011           const ComponentID compIDsrc=ComponentID((comp+1)%numValidComp);
01012           const ComponentID compIDdst=ComponentID(comp);
01013           copyPlane(src, bIsForwards?compIDsrc:compIDdst, dest, bIsForwards?compIDdst:compIDsrc);
01014         }
01015       }
01016       break;
01017 
01018     case IPCOLOURSPACE_UNCHANGED:
01019     default:
01020       {
01021         for(UInt comp=0; comp<numValidComp; comp++)
01022         {
01023           copyPlane(src, ComponentID(comp), dest, ComponentID(comp));
01024         }
01025       }
01026       break;
01027   }
01028 }
